    "decir": ["Mi abuela dice que la comida está lista.","My grandma says the food is ready."],
    "ir": ["Voy a la playa con mis amigos.","I'm going to the beach with my friends."],
    "ver": ["Vemos una película los viernes.","We watch a movie on Fridays."],
    "dar": ["¿Me das tu número de teléfono?","Will you give me your phone number?"],
