      ["\"Houses for sale\" on a sign is…",["Se vende casas.","Se venden casas.","Vende casas.","Se venden casa."],1,"casas is plural, so standard written Spanish makes the verb plural too: se venden."],
      ["\"How do you say this in Spanish?\" (asking in general) is…",["¿Cómo se dices esto en español?","¿Cómo dice se esto en español?","¿Cómo se dice esto en español?","¿Cómo se decir esto en español?"],2,"se + the él form of decir: se dice."]
