      {"t":"fill","q":"__ camisa es bonita.","p":"This shirt is pretty.","a":["Esta"],"o":["Este","Está","Esto"],"why":"Esta agrees with camisa; está with an accent mark means is.","strict":true},
      {"t":"type","p":"My parents are from Arecibo.","a":["Mis padres son de Arecibo.","Mis papás son de Arecibo."],"hint":"mis padres · ser de · Arecibo","x":["Mi"],"why":"Mis agrees with padres (plural), and son matches the subject."},
      {"t":"type","p":"This house is big.","a":["Esta casa es grande."],"hint":"esta · la casa · grande","x":["Este"],"why":"Esta agrees with casa, which is feminine.","strict":true},
      {"t":"type","p":"Where is your car? (to a friend)","a":["¿Dónde está tu carro?"],"hint":"dónde · estar · tu · el carro","x":["es"],"why":"Where something is takes estar, and tu (your) has no accent mark.","strict":true}
